CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sensors (id text PRIMARY KEY, device_id text UNIQUE NOT NULL, document jsonb NOT NULL, location geography(Point,4326) NOT NULL, archived boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS sensors_location_idx ON sensors USING gist(location);
CREATE TABLE IF NOT EXISTS sensor_locations (sensor_id text REFERENCES sensors(id) ON DELETE CASCADE, version integer NOT NULL, effective_at timestamptz NOT NULL, location geography(Point,4326) NOT NULL, document jsonb NOT NULL, PRIMARY KEY(sensor_id,version));
CREATE TABLE IF NOT EXISTS device_credentials (id text PRIMARY KEY, token_hash text UNIQUE NOT NULL, sensor_ids text[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, username text NOT NULL, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS telemetry (id text PRIMARY KEY, sensor_id text NOT NULL REFERENCES sensors(id) ON DELETE CASCADE, message_id text, recorded_at timestamptz NOT NULL, received_at timestamptz NOT NULL, document jsonb NOT NULL, UNIQUE(sensor_id,message_id));
CREATE INDEX IF NOT EXISTS telemetry_sensor_time_idx ON telemetry(sensor_id,recorded_at,id);
CREATE TABLE IF NOT EXISTS sensor_latest (sensor_id text PRIMARY KEY REFERENCES sensors(id) ON DELETE CASCADE, recorded_at timestamptz NOT NULL, document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS telemetry_hourly (sensor_id text REFERENCES sensors(id) ON DELETE CASCADE, hour timestamptz, channel text, count integer NOT NULL, min double precision, max double precision, mean double precision, PRIMARY KEY(sensor_id,hour,channel));
CREATE TABLE IF NOT EXISTS environment_snapshots (id text PRIMARY KEY, document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scenarios (id text PRIMARY KEY, revision integer NOT NULL, document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS scenario_versions (scenario_id text NOT NULL REFERENCES scenarios(id) ON DELETE CASCADE, revision integer NOT NULL, document jsonb NOT NULL, PRIMARY KEY(scenario_id,revision));
CREATE TABLE IF NOT EXISTS scenario_events (id bigserial PRIMARY KEY, scenario_id text NOT NULL, revision integer NOT NULL, event_time timestamptz NOT NULL DEFAULT now(), type text NOT NULL, document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS simulation_checkpoints (scenario_id text NOT NULL, revision integer NOT NULL, time_sec integer NOT NULL, document bytea NOT NULL, PRIMARY KEY(scenario_id,revision,time_sec));
CREATE TABLE IF NOT EXISTS simulation_frames (scenario_id text NOT NULL, revision integer NOT NULL, time_sec integer NOT NULL, document bytea NOT NULL, PRIMARY KEY(scenario_id,revision,time_sec));
CREATE TABLE IF NOT EXISTS simulation_readings (id text PRIMARY KEY, scenario_id text NOT NULL, revision integer NOT NULL, sensor_id text NOT NULL, time_sec integer NOT NULL, document jsonb NOT NULL, UNIQUE(scenario_id,revision,sensor_id,time_sec));
CREATE INDEX IF NOT EXISTS simulation_readings_lookup_idx ON simulation_readings(scenario_id,revision,sensor_id,time_sec);
CREATE TABLE IF NOT EXISTS event_outbox (cursor bigserial PRIMARY KEY, event_id text UNIQUE NOT NULL, context text NOT NULL, scenario_id text, revision integer, event_time timestamptz NOT NULL DEFAULT now(), type text NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS event_outbox_context_idx ON event_outbox(context,scenario_id,cursor);
CREATE TABLE IF NOT EXISTS analysis_jobs (id text PRIMARY KEY, kind text NOT NULL, scenario_id text, revision integer, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, owner text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), error text);
CREATE INDEX IF NOT EXISTS analysis_jobs_claim_idx ON analysis_jobs(status,lease_until,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS analysis_jobs_scenario_active_idx ON analysis_jobs(scenario_id,revision,kind) WHERE status IN ('queued','running') AND scenario_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS prediction_runs (id text PRIMARY KEY, scenario_id text, revision integer, time_sec integer, issued_at timestamptz NOT NULL, document jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS prediction_lookup_idx ON prediction_runs(scenario_id,revision,time_sec);
CREATE TABLE IF NOT EXISTS incidents (id text PRIMARY KEY, sensor_id text NOT NULL, context text NOT NULL, scenario_id text, revision integer, observed_at timestamptz NOT NULL, document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS incident_evidence (incident_id text NOT NULL, observation_id text NOT NULL, PRIMARY KEY(incident_id,observation_id));
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, at timestamptz NOT NULL DEFAULT now(), actor text NOT NULL, action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS external_detections (id text PRIMARY KEY, observed_at timestamptz NOT NULL, received_at timestamptz NOT NULL, document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS model_versions (id text PRIMARY KEY, document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS dataset_manifests (id text PRIMARY KEY, document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS worker_heartbeats (id text PRIMARY KEY, last_seen timestamptz NOT NULL, status text NOT NULL);
CREATE TABLE IF NOT EXISTS provider_cache (key text PRIMARY KEY, fetched_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, document jsonb NOT NULL);
